// Server action to invalidate the products cache
async function invalidateProductsCache() {
  'use server';

  // Invalidate the "products" cache tag
  revalidateTag('products');
  return { success: true };
}

// Client component that uses cached data
export default function ProductList() {
  const [isInvalidating, setIsInvalidating] = useState(false);
  const [cacheKey, setCacheKey] = useState(0);

  // Fetch products with cache directive
  const fetchProducts = async () => {
    'use cache'; // Enable caching for this function

    // Simulate the cache tag assignment
    return await getAllProducts();
  };

  const handleInvalidateCache = async () => {
    setIsInvalidating(true);
    try {
      await invalidateProductsCache();
      // Force a re-render to trigger cache invalidation
      setCacheKey(prev => prev + 1);
      console.log('Cache invalidation requested');
