'use client';

import { useState } from 'react';
import { useCache } from '@ai-sdk/react';
import { getAllProducts } from '@/lib/db';

// Cache the product data with a "products" cache tag
const useCachedProducts = () => {
  return useCache({
    key: 'products',
    fetcher: getAllProducts,
    tags: ['products'],
    staleTime: 300000, // 5 minutes
  });
};

// Server action to invalidate the products cache
async function invalidateProductsCache() {
  'use server';

  // This would typically trigger an actual invalidation mechanism
  // For demonstration, we'll just log and return success
  console.log('Cache invalidated for products tag');
  return { success: true };
}

export default function ProductList() {
  const { data: products, isLoading, error } = useCachedProducts();
  const [isInvalidating, setIsInvalidating] = useState(false);

  const handleInvalidateCache = async () => {
    setIsInvalidating(true);
    try {
      await invalidateProductsCache();
      // The cache would be invalidated here, triggering a refetch
      console.log('Cache invalidation requested');
    } catch (err) {
      console.error('Failed to invalidate cache:', err);
    } finally {
      setIsInvalidating(false);
    }
  };

  if (isLoading) {
    return (
      <div>
        <p>Loading products...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div>
        <p>Error loading products: {error.message}</p>
      </div>
    );
  }

  return (
    <div>
      <div style={{ marginBottom: '1rem', padding: '1rem', border: '1px solid #ccc', borderRadius: '4px' }}>
        <h2>Products ({products?.length || 0})</h2>
        <form 
          onSubmit={(e) => {
            e.preventDefault();
            handleInvalidateCache();
          }}
        >
          <button 
            type="submit" 
            disabled={isInvalidating}
            style={{
              padding: '8px 16px',
              backgroundColor: isInvalidating ? '#ccc' : '#007bff',
