'use client';

import { useState } from 'react';
import { revalidateTag } from 'next/cache';

// Client component that handles the cache invalidation form
// This demonstrates inline server actions with cache invalidation
export default function ProductList() {
  const [isInvalidating, setIsInvalidating] = useState(false);
  const [lastInvalidated, setLastInvalidated] = useState<Date | null>(null);

  // Server action to invalidate the products cache
  // This is an inline server action that runs on the server
  const invalidateProductsCache = async () => {
    'use server';

    // Invalidate the "products" cache tag
    // This will clear all cached data associated with the "products" tag
    revalidateTag('products');
    return { success: true };
  };

  const handleInvalidateCache = async () => {
    setIsInvalidating(true);
    try {
      await invalidateProductsCache();
      setLastInvalidated(new Date());
      console.log('Cache invalidation requested');
    } catch (err) {
      console.error('Failed to invalidate cache:', err);
    } finally {
      setIsInvalidating(false);
    }
  };

  return (
    <div>
      <div style={{ marginBottom: '1rem', padding: '1rem', border: '1px solid #ccc', borderRadius: '4px' }}>
        <h2>Products ({lastInvalidated ? 'Cache invalidated' : 'Cached'})</h2>

        {lastInvalidated && (
          <div style={{ 
            marginBottom: '1rem', 
            padding: '0.5rem', 
            backgroundColor: '#d4edda', 
            border: '1px solid #c3e6cb',
            borderRadius: '4px',
            fontSize: '0.875rem',
            color: '#155724'
          }}>
            Cache was invalidated at {lastInvalidated.toLocaleTimeString()}
          </div>
        )}

        <form 
          onSubmit={(e) => {
            e.preventDefault();
            handleInvalidateCache();
          }}
        >
          <button 
            type="submit" 
            disabled={isInvalidating}
            style={{
              padding: '12px 24px',
              backgroundColor: isInvalidating ? '#ccc' : '#007bff',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              cursor: isInvalidating ? 'not-allowed' : 'pointer',
              fontWeight: 'bold',
              fontSize: '1rem',
              boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
            }}
            onMouseEnter={(e) => {
              if (!isInvalidating) {
                e.currentTarget.style.backgroundColor = '#0056b3';
              }
            }}
            onMouseLeave={(e) => {
              if (!isInvalidating) {
                e.currentTarget.style.backgroundColor = '#007bff';
              }
            }}
          >
            {isInvalidating ? 'Invalidating Cache...' : 'Invalidate Products Cache'}
          </button>

          <div style={{ marginTop: '1rem', fontSize: '0.875rem', color: '#666' }}>
            <strong>Cache Invalidation Details:</strong>
            <ul style={{ marginTop: '0.5rem', paddingLeft: '1.5rem' }}>
              <li>This form demonstrates inline server actions</li>
              <li>Clicking the button invalidates the "products" cache tag</li>
              <li>The server action runs on the server, not in the browser</li>
              <li>Cache invalidation is selective - only "products" tag is cleared</li>
              <li>The product list will refetch data after cache invalidation</li>
            </ul>
          </div>
        </form>
      </div>
    </div>
  );
}

